-- Schema-only QA fixture. No customer rows copied from production.
CREATE TABLE orders (id INTEGER PRIMARY KEY AUTOINCREMENT,order_number TEXT NOT NULL UNIQUE,customer_name TEXT NOT NULL,customer_phone TEXT NOT NULL,customer_city TEXT NOT NULL,customer_address TEXT NOT NULL,customer_comment TEXT DEFAULT '',total_amount INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'new',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_items(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,product_id TEXT NOT NULL,product_name TEXT NOT NULL,price INTEGER NOT NULL,quantity INTEGER NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE telegram_link_tokens(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,used_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE telegram_customers(id INTEGER PRIMARY KEY AUTOINCREMENT,telegram_id TEXT NOT NULL UNIQUE,telegram_username TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_telegram_links(order_id INTEGER PRIMARY KEY,telegram_customer_id INTEGER NOT NULL,linked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(telegram_customer_id) REFERENCES telegram_customers(id));
CREATE TABLE products(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',category TEXT NOT NULL,price INTEGER NOT NULL,sale_price INTEGER,stock INTEGER NOT NULL DEFAULT 0,track_stock INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE product_images(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id TEXT NOT NULL,image_key TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id));
